// Function Item node
const item = items[0].json;

// Use the real IP from x-forwarded-for header as the customer key
const customerKey = item.headers?.['x-forwarded-for'] || item.headers?.['x-real-ip'] || 'unknown-ip';

// Deterministic UUID generation from IP
function xmur3(str) {
    for(var i = 0, h = 1779033703 ^ str.length; i < str.length; i++)
        h = Math.imul(h ^ str.charCodeAt(i), 3432918353),
        h = h << 13 | h >>> 19;
    return function() {
        h = Math.imul(h ^ h >>> 16, 2246822507),
        h = Math.imul(h ^ h >>> 13, 3266489909);
        return (h ^= h >>> 16) >>> 0;
    }
}

function sfc32(a, b, c, d) {
    return function() {
        a >>>= 0; b >>>= 0; c >>>= 0; d >>>= 0;
        var t = (a + b) | 0;
        a = b ^ b >>> 9;
        b = c + (c << 3) | 0;
        c = (c << 21 | c >>> 11);
        d = d + 1 | 0;
        t = t + d | 0;
        c = c + t | 0;
        return (t >>> 0) / 4294967296;
    }
}

function uuidFromString(str) {
    const seed = xmur3(str);
    const rand = sfc32(seed(), seed(), seed(), seed());

    const hex = () => Math.floor(rand() * 16).toString(16);
    const uuid = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
        return c === 'x' ? hex() : (parseInt(hex(), 16) & 0x3 | 0x8).toString(16);
    });
    return uuid;
}

// Generate consistent sessionId from IP
item.sessionId = uuidFromString(customerKey);

console.log('IP Address:', customerKey);
console.log('Generated sessionId:', item.sessionId);

return [{ json: item }];

// Get input text from webhook body
const raw = items[0].json.body?.message || '';

// Burmese Unicode blocks
const burRegex = /[\u1000-\u109F\uAA60-\uAA7F]/g;
// English letters
const engRegex = /[A-Za-z]/g;

const burMatches = raw.match(burRegex) || [];
const engMatches = raw.match(engRegex) || [];

const burCount = burMatches.length;
const engCount = engMatches.length;

// Decide dominant language
let dominant = 'burmese';
if (burCount + engCount > 0) {
  if (burCount > engCount) dominant = 'burmese';
  else if (engCount > burCount) dominant = 'english';
  else dominant = 'burmese'; // tie → fallback to Burmese
} else {
  dominant = 'burmese'; // no recognizable chars → fallback to Burmese
}

// Return enriched fields
return [{
  json: {
    containsBurmese: burCount > 0,
    containsEnglish: engCount > 0,
    burCount,
    engCount,
    dominantLanguage: dominant,
    originalText: raw
  }
}];

// Get the agent output
const text = items[0].json.output;

// Step 1: Remove markdown headings (###, ##, #)
let cleanedText = text.replace(/^#{1,6}\s*/gm, '');

// Step 2: Remove bold/italic markers (** or )
cleanedText = cleanedText.replace(/**|/gm, '');

// Step 3: Convert numbered lists to bullets
cleanedText = cleanedText.replace(/^\d+.\s+/gm, '- ');

const content = $input.first().json.output;

let plainText = content
  // Remove code blocks
  .replace(/```[\s\S]*?```/g, '')
  // Remove inline code
  .replace(/`([^`]+)`/g, '$1')
  // Remove bold/italic formatting
  .replace(/\*\*\*(.+?)\*\*\*/g, '$1')  // bold+italic
  .replace(/\*\*(.+?)\*\*/g, '$1')      // bold
  .replace(/\*(.+?)\*/g, '$1')          // italic
  .replace(/__(.+?)__/g, '$1')          // bold underline
  .replace(/_(.+?)_/g, '$1')            // italic underline
  // Convert markdown headers to plain lines
  .replace(/^#{1,6}\s*(.+)$/gm, '$1')
  // Convert markdown bullet points (*, -, +) to plain bullets
  .replace(/^\s*[-*+]\s+/gm, '• ')
  // Keep numbered lists like "1. ", "2. "
  .replace(/^\s*(\d+)\.\s+/gm, '$1. ')
  // Remove markdown links but keep text
  .replace(/\[([^\]]+)\]\([^)]+\)/g, '$1')
  // Remove images ![alt](url)
  .replace(/!\[.*?\]\(.*?\)/g, '')
  // Remove blockquotes
  .replace(/^>\s?/gm, '')
  // Clean extra spaces and blank lines
  .replace(/\n{3,}/g, '\n\n')
  .replace(/[ \t]+$/gm, '')
  .trim();

return [{
  json: {
    output: plainText
  }
}];

const input = $input.first().json;

// Safely get text from possible fields
const text = input.chatInput || input.body?.chatInput || input.body?.message || '';

// Regex for Burmese Unicode
const burmeseRegex = /[\u1000-\u109F]/;

// Return as "Yes"/"No" string
return {
  ...input,
  containsBurmese: burmeseRegex.test(text) ? "Yes" : "No"
};

// Default Return Template
return {
  "output": "This message does not follow our community guidelines and cannot be processed."
};

